-- 116_ficha_producao_saude_estoque_tela.sql
-- Ficha do Gerenciamento de Produção: tela da Saúde do Estoque (S2 do plano). Aditiva e idempotente.

UPDATE mapa_modules SET
    detail = jsonb_set(detail, '{attention}', COALESCE(detail->'attention', '[]'::jsonb) || to_jsonb('Tela Saúde do Estoque (Administrativo > Relatórios, componente StockHealthTab): lê só o endpoint saude-estoque, sem cálculo no navegador. Três listas com contagem (Disponibilidade = ruptura e baixo, Excesso, Sem giro) mais Todos, com busca, filtro de tipo e linha, ordenação por coluna e impressão da lista em uso; no celular a tabela vira linhas compactas. Disponibilidade tem + Fila (mesma fila de demandas da Demanda); Sem giro tem atalho para Administrativo > Linha de Produtos, onde se inativa (a Produção não grava situação). Clique abre o ProductDetailsDrawer. Coloração e ocultos (com as exclusões manuais) continuam acessíveis na aba Coloração e ocultos (versão anterior), que é a tela antiga (StockHealthLegadoTab) até a etapa de Coloração e Apoio'::text)),
    updated_at = NOW()
WHERE module_key = 'producao'
  AND NOT (COALESCE(detail->'attention', '[]'::jsonb) @> to_jsonb('Tela Saúde do Estoque (Administrativo > Relatórios, componente StockHealthTab): lê só o endpoint saude-estoque, sem cálculo no navegador. Três listas com contagem (Disponibilidade = ruptura e baixo, Excesso, Sem giro) mais Todos, com busca, filtro de tipo e linha, ordenação por coluna e impressão da lista em uso; no celular a tabela vira linhas compactas. Disponibilidade tem + Fila (mesma fila de demandas da Demanda); Sem giro tem atalho para Administrativo > Linha de Produtos, onde se inativa (a Produção não grava situação). Clique abre o ProductDetailsDrawer. Coloração e ocultos (com as exclusões manuais) continuam acessíveis na aba Coloração e ocultos (versão anterior), que é a tela antiga (StockHealthLegadoTab) até a etapa de Coloração e Apoio'::text));
